"""Differential test: compare my ignored_files against git on random trees/.gitignore files."""
import os
import random
import shutil
import subprocess
import sys
import tempfile

sys.path.insert(0, '/work/repo')
from snapshot.ignore import ignored_files


_GIT = ["git", "-c", "core.ignorecase=false", "-c", "core.excludesFile=" + os.devnull]


def git_ignored(root):
    """Reference implementation using git."""
    with tempfile.TemporaryDirectory() as tmp:
        repo = os.path.join(tmp, "repo")
        shutil.copytree(root, repo, symlinks=True,
                        ignore=lambda d, names: [".git"] if os.path.samefile(d, root) else [])
        env = {
            "PATH": os.environ.get("PATH", ""),
            "HOME": tmp,
            "XDG_CONFIG_HOME": tmp,
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": os.devnull,
        }
        subprocess.run(_GIT + ["init", "-q", "--template="], cwd=repo, env=env,
                       check=True, capture_output=True)
        out = subprocess.run(_GIT + ["ls-files", "-z", "--others", "--ignored", "--exclude-standard"],
                             cwd=repo, env=env, check=True, capture_output=True).stdout
    return sorted(p for p in out.decode().split("\0") if p)


def make_random_tree(root, rng, depth=3, max_files=15, max_dirs=4):
    """Create a random tree with files, dirs, and some .gitignore files."""
    names_pool = ["foo", "bar", "baz", "qux", "a", "b", "c", "x", "y", "data",
                  "test", "src", "lib", "build", "dist", "node_modules",
                  "readme", "config", "setup", "app", "main", "util"]
    exts = ["", ".txt", ".log", ".py", ".o", ".js", ".md", ".json", ".tmp"]

    def recurse(path, d):
        n_files = rng.randint(0, max_files)
        for _ in range(n_files):
            name = rng.choice(names_pool) + rng.choice(exts)
            fp = os.path.join(path, name)
            try:
                with open(fp, "w") as f:
                    f.write("x\n")
