    choices = string.ascii_lowercase + "._-"
    n = rng.randint(1, 8)
    pat = ""
    for _ in range(n):
        r = rng.random()
        if r < 0.1:
            pat += "*"
        elif r < 0.15:
            pat += "**"
        elif r < 0.2:
            pat += "?"
        elif r < 0.25:
            pat += "/"
        elif r < 0.3:
            pat += rng.choice("[abc]") if rng.random() < 0.5 else "[abc]"
        elif r < 0.33:
            pat += "[!abc]"
        elif r < 0.4:
            pat += ""
        else:
            pat += rng.choice(choices)
    prefix = ""
    if rng.random() < 0.25:
        prefix = "!"
    if rng.random() < 0.2:
        prefix += "/"
    pat = prefix + pat
    if rng.random() < 0.2:
        pat += "/"
    return pat


