    dirs = []
    for d, _, _ in os.walk(root):
        dirs.append(d)
    k = rng.randint(1, min(3, len(dirs)))
    rng.shuffle(dirs)
    for d in dirs[:k]:
        try:
            with open(os.path.join(d, ".gitignore"), "w") as f:
