                    j += 2
                else:
                    j += 1
            if j >= n:
                out.append(re.escape("["))
                i += 1
            else:
                raw = pat[content_start:j]
                parts = ["["]
                if negated:
                    parts.append("^")
                k = 0
                while k < len(raw):
                    ch = raw[k]
                    if ch == "\\" and k + 1 < len(raw):
                        parts.append(re.escape(raw[k + 1]))
                        k += 2
                    elif ch == "]":
                        parts.append(r"\]")
                        k += 1
                    elif ch == "\\":
                        parts.append(r"\\")
                        k += 1
                    else:
                        parts.append(ch)
                        k += 1
